import React from 'react';
import { motion } from 'framer-motion';

const AttentionHeatmap = ({ days }) => {
  if (!days?.length) return null;
  const maxImp = Math.max(...days.map(d => d.importance), 1e-9);

  return (
    <motion.div
      className="card attention-heatmap-card"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45, delay: 0.18 }}
    >
      <div className="card-title">
        <div className="card-ico ico-p">👁️</div>
        <span className="card-title-text">Attention — Key Historical Days</span>
      </div>

      <div className="sub-note">Days the model focused on within the 60-day window</div>

      <div className="day-list">
        {days.map((day, i) => {
          const pct = (day.importance / maxImp) * 100;
          const label = day.days_ago === 0 ? 'Today' : `${day.days_ago} days ago`;
          return (
            <motion.div
              key={day.day_index}
              className="day-item"
              initial={{ opacity: 0, x: 16 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.2 + i * 0.08 }}
            >
              <span className="day-rank">#{i + 1}</span>
              <div className="day-info">
                <div className="day-label">{label}</div>
                <div className="day-importance">idx {day.day_index}</div>
              </div>
              <div className="day-bar">
                <motion.div
                  className="day-bar-fill"
                  initial={{ width: 0 }}
                  animate={{ width: `${pct}%` }}
                  transition={{ duration: 0.9, delay: 0.3 + i * 0.08 }}
                />
              </div>
              <span className="day-imp-val">{day.importance.toFixed(3)}</span>
            </motion.div>
          );
        })}
      </div>

      <div className="tip-box" style={{ marginTop: 16 }}>
        💡 Higher importance = the model paid more attention to that historical day. Recent days typically score higher.
      </div>
    </motion.div>
  );
};

export default AttentionHeatmap;
